    int minNumberOfFrogs(string croakOfFrogs) {
        int c = 0, r = 0, o = 0, a = 0, frogs = 0, maxFrogs = 0;
        for (char ch : croakOfFrogs) {
            if (ch == 'c') {
                c++; frogs++;
                maxFrogs = max(maxFrogs, frogs);
            } else if (ch == 'r') {
                if (c == 0) return -1;
                c--; r++;
            } else if (ch == 'o') {
                if (r == 0) return -1;
                r--; o++;
            } else if (ch == 'a') {
                if (o == 0) return -1;
                o--; a++;
            } else if (ch == 'k') {
                if (a == 0) return -1;
                a--; frogs--;
            } else {
                return -1;
            }
        }
        return (frogs == 0 && c == 0 && r == 0 && o == 0 && a == 0) ? maxFrogs : -1;
    }
};

